
ALTER TABLE tenant ADD COLUMN enabled BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE app_user ADD COLUMN enabled BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE campus ADD COLUMN enabled BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE department ADD COLUMN enabled BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE doctor ADD COLUMN enabled BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE doctor ADD COLUMN account_id BIGINT REFERENCES app_user(id);
CREATE UNIQUE INDEX uk_doctor_account ON doctor(account_id) WHERE account_id IS NOT NULL;
CREATE UNIQUE INDEX uk_campus_name ON campus(tenant_id,name);
CREATE UNIQUE INDEX uk_department_name ON department(tenant_id,name);
CREATE TABLE doctor_department (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tenant_id BIGINT NOT NULL REFERENCES tenant(id),doctor_id BIGINT NOT NULL REFERENCES doctor(id),department_id BIGINT NOT NULL REFERENCES department(id), UNIQUE(doctor_id,department_id));
CREATE TABLE doctor_campus (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenant(id),doctor_id BIGINT NOT NULL REFERENCES doctor(id),campus_id BIGINT NOT NULL REFERENCES campus(id), UNIQUE(doctor_id,campus_id));
INSERT INTO doctor_department(tenant_id,doctor_id,department_id) SELECT tenant_id,id,department_id FROM doctor;
INSERT INTO doctor_campus(tenant_id,doctor_id,campus_id) SELECT DISTINCT s.tenant_id,s.doctor_id,s.campus_id FROM clinic_schedule s;
ALTER TABLE clinic_schedule ADD COLUMN department_id BIGINT REFERENCES department(id);
UPDATE clinic_schedule s SET department_id=d.department_id FROM doctor d WHERE d.id=s.doctor_id;
ALTER TABLE clinic_schedule ALTER COLUMN department_id SET NOT NULL;
CREATE TABLE patient_profile(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenant(id),owner_id BIGINT NOT NULL REFERENCES app_user(id),name VARCHAR(80) NOT NULL,relationship VARCHAR(20) NOT NULL,authorized BOOLEAN NOT NULL DEFAULT TRUE,self_profile BOOLEAN NOT NULL DEFAULT FALSE);
CREATE UNIQUE INDEX uk_self_profile ON patient_profile(tenant_id,owner_id) WHERE self_profile=TRUE;
INSERT INTO patient_profile(tenant_id,owner_id,name,relationship,authorized,self_profile) SELECT tenant_id,id,display_name,'SELF',TRUE,TRUE FROM app_user WHERE role='PATIENT';
ALTER TABLE appointment ADD COLUMN patient_id BIGINT REFERENCES patient_profile(id);
UPDATE appointment a SET patient_id=p.id FROM patient_profile p WHERE a.tenant_id=p.tenant_id AND a.user_id=p.owner_id AND p.self_profile=TRUE;
CREATE INDEX idx_schedule_department ON clinic_schedule(tenant_id,department_id,start_at);
